  AsyncDialLookup soundBusy("Sound file","Cannot validate sound files.");bool soundRefused=false;try{soundBusy.request([]{return AsyncDialLookup::Value(true);});}catch(const std::exception& e){soundRefused=std::string(e.what())=="Sound file lookup is busy. Try again shortly.";}check(soundRefused&&!soundBusy.pending(),"Per-receiver feature text reports bounded sound lookup admission without connection-specific wording");
