  a->release();until([&]{return latestNotify==1;});check(latest.pending(),"Published metadata stays pending until the owner consumes its delivery");check(user(latest)=="11"&&executed==1,"Repeated queued requests coalesce to exactly the newest action");check(!latest.pending()&&!latest.take(),"Consuming metadata clears pending state and cannot redeliver the same result");
