  finalFence.request([]{return AsyncDialLookup::Value(true);},[&]{++finalDone;});until([&]{return finalDone==2;});check(finalFence.pending(),"Published startup metadata remains pending until UI delivery");auto startup=finalFence.take();check(startup&&startup->value&&std::get<bool>(*startup->value),"Startup metadata has its own boolean result type");
